def parse_price(s: str) -> float:
    import re
    match = re.search(r'\$?\d{1,3}(?:,\d{3})*(?:\.\d{2})?', s)
    if not match:
        return 0.0
    price_str = match.group().replace('$', '').replace(',', '')
    return float(price_str)

